	write(MeteringMode, 0x0000
	| BaseFrequency=="60" ? 0x1000 : 0x0000);
	write(I_RatioA, CurrentRatioA);
	write(I_RatioB, CurrentRatioB);
	write(I_RatioC, CurrentRatioC);
	write(I_RatioN, CurrentRatioN);
