else
{
	write(Cs0Update,0xffff);
	write(CfgUpdate,0xffff);
	write(ChanControl, 0x0000
	| EnRegStatA=="on" ? 0x0001 : 0x0000
	| EnRegStatB=="on" ? 0x0002 : 0x0000
	| EnRegStatC=="on" ? 0x0004 : 0x0000
	| EnableTestN=="on" ? 0x0010 : 0x0000
	| ConfigPhaseN=="meas" ? 0x0020 : 0x0000
	| EnergyUnit=="1kWh" ? 0x0040 : 0x0000
	| EnergyUnit=="1Wh" ? 0x0040 : 0x0000
	| EnabCurrDisp=="on" ? 0x0080 : 0x0000);
