		| ZeroCroConnectA=="posneg" ? 0x0004 : 0x0000
		| ZeroCroConnectB=="negative" ? 0x0008 : 0x0000
		| ZeroCroConnectB=="posneg" ? 0x0010 : 0x0000
		| ZeroCroConnectC=="negative" ? 0x0020 : 0x0000
		| ZeroCroConnectC=="posneg" ? 0x0040 : 0x0000
