		| ZeroCroSourceB=="Current" ? 0x1400 : 0x0400
		| ZeroCroSourceC=="Current" ? 0xC000 : 0x4000);
	}
	if (VoltageLimit=="off")
	{
	}
	else
	{
		write(SagTh, VoltageWarnLim);
		write(PhaseLoseTh, VoltageLossLim);
		write(THDNUTh, THDVoltageLimit);
		write(THDNITh, THDCurrentLimit);
	}
	write(Cs0Update,1);
	write(CfgUpdate,1);
	if (FlatStreamActivate=="on")
	{
		write(InputMTU, 0x00
		| InputMTU=="3byte" ? 0x03 : 0x00
